package com.aistock.market.refresh;
import com.aistock.market.calendar.*;import com.sun.net.httpserver.HttpServer;import java.net.InetSocketAddress;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class CalendarCollectorHttpTest {
 @Test void sendsIsoDatesAndRejectsCoercedOpenFlag()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var bad=new boolean[1];server.createContext("/internal/v1/market/calendar-collect",e->{var body=new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);boolean correct=body.contains("\"start\":\"2026-10-09\"")&&"fixture".equals(e.getRequestHeaders().getFirst("X-Service-Token"));String json="{\"operationId\":\"http-test\",\"state\":\"AVAILABLE\",\"errorCode\":null,\"candidate\":{\"provider\":\"baostock\",\"start\":\"2026-10-09\",\"end\":\"2026-10-09\",\"fetchedAt\":\"2026-10-10T06:00:00Z\",\"sourcePayloadHash\":\""+"a".repeat(64)+"\",\"days\":[{\"date\":\"2026-10-09\",\"open\":"+(bad[0]?"1":"true")+"}]}}";var bytes=json.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(correct?200:422,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var client=new CalendarCollectorClient("http://127.0.0.1:"+server.getAddress().getPort(),"fixture");var request=new CalendarRecords.Request("http-test",LocalDate.of(2026,10,9),LocalDate.of(2026,10,9));assertTrue(client.collect(request).days().get(0).open());bad[0]=true;assertThrows(com.aistock.common.BusinessException.class,()->client.collect(request));}finally{server.stop(0);}}
}
